        static void RequireRecordedStartupSourceHash(FlightSourceHash[] manifest,string path,string context)
        {
            string normalized=path.Replace('\\','/');var matches=manifest.Where(value=>string.Equals(value.path.Replace('\\','/'),normalized,StringComparison.OrdinalIgnoreCase)).ToArray();
