            if(matches.Length!=1)throw new InvalidOperationException(context+" missing or ambiguous actual recorded dependency: "+path+" currentSha256="+Hash(path)+" sameFileNameCandidates="+string.Join(";",manifest.Where(value=>string.Equals(Path.GetFileName(value.path),Path.GetFileName(path),StringComparison.OrdinalIgnoreCase)).Select(value=>value.path)));
            if(!string.Equals(Hash(path),matches[0].sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException(context+" current source provenance changed: "+path);
        }
